# Phase 2: store and accept a rating

Class: ACT. Tenant scoping is a hot path: independent review in phase 5. Decisions D3-D7, D11.

Context: spec requirements 1-3; `src/portal.js:10-14` (`getMyTicket` is the isolation pattern),
`src/portal.js:21-28` (`reply`, the error style), `src/store.js:19-24`, `src/tickets.js:8-23`.

## Requirements

- `rating_score` and `rated_at` exist on every new ticket, `null` until rated.
- `portal.rateTicket(store, customer, id, score, { now })` stores the score and time on a resolved ticket of the
  customer's organisation and returns the ticket as `getMyTicket` does.
- Refused with an `Error`: score not an integer from 1 to 5; status not `resolved` (open, pending, closed); already rated.
- Returns `null`, identical to a missing ticket, for another organisation's ticket.
- The second attempt leaves the first rating untouched.

## Steps

- [ ] 1. Create `test/rating.test.js`:
  ```js
  'use strict';
  const test = require('node:test');
  const assert = require('node:assert/strict');
  const { createStore } = require('../src/store');
  const { STATUS, createTicket, resolveTicket } = require('../src/tickets');
  const portal = require('../src/portal');

  const acme = { id: 7, orgId: 1 };
  const globex = { id: 9, orgId: 2 };
  const T0 = new Date(Date.UTC(2026, 0, 1));

  function resolved(store) {
    const t = createTicket(store, { orgId: 1, customerId: 7, subject: 'Printer', body: 'x', now: T0 });
    resolveTicket(store, t.id, 41, { now: T0 });
    return t;
  }

  test('a customer rates a resolved ticket of their organisation', () => {
    const store = createStore();
    const t = resolved(store);
    const out = portal.rateTicket(store, acme, t.id, 4, { now: T0 });
    assert.equal(out.rating_score, 4);
    assert.equal(out.rated_at, T0.toISOString());
    assert.equal(store.getTicket(t.id).rating_score, 4);
  });

  test('a score that is not a whole number from 1 to 5 is refused', () => {
    const store = createStore();
    const t = resolved(store);
    for (const bad of [0, 6, 3.5, -1, '4', NaN, null, undefined]) {
      assert.throws(() => portal.rateTicket(store, acme, t.id, bad), /whole number from 1 to 5/);
    }
    assert.equal(store.getTicket(t.id).rating_score, null);
  });

  test('an open, pending or closed ticket cannot be rated', () => {
    const store = createStore();
    const open = createTicket(store, { orgId: 1, customerId: 7, subject: 'a', body: 'x', now: T0 });
    assert.throws(() => portal.rateTicket(store, acme, open.id, 5), /cannot rate a open ticket/);
    store.updateTicket(open.id, { status: STATUS.PENDING });
    assert.throws(() => portal.rateTicket(store, acme, open.id, 5), /cannot rate a pending ticket/);
    store.updateTicket(open.id, { status: STATUS.CLOSED });
    assert.throws(() => portal.rateTicket(store, acme, open.id, 5), /cannot rate a closed ticket/);
    assert.equal(store.getTicket(open.id).rating_score, null);
  });

  test('a second rating is refused and the first stays', () => {
    const store = createStore();
    const t = resolved(store);
    portal.rateTicket(store, acme, t.id, 4, { now: T0 });
    assert.throws(() => portal.rateTicket(store, acme, t.id, 1, { now: new Date(T0.getTime() + 1000) }), /already been rated/);
    const kept = store.getTicket(t.id);
    assert.equal(kept.rating_score, 4);
    assert.equal(kept.rated_at, T0.toISOString());
  });

  test('another organisation gets the same answer as for a ticket that does not exist, even with a bad score', () => {
    const store = createStore();
    const t = resolved(store);
    assert.equal(portal.rateTicket(store, globex, t.id, 4), null);
    assert.equal(portal.rateTicket(store, globex, t.id, 99), null);
    assert.equal(portal.rateTicket(store, globex, 999, 4), null);
    assert.equal(store.getTicket(t.id).rating_score, null);
  });

  test('a rating survives a reopen and the ticket cannot be rated again', () => {
    const store = createStore();
    const t = resolved(store);
    portal.rateTicket(store, acme, t.id, 5, { now: T0 });
    portal.reply(store, acme, t.id, 'still broken');
    resolveTicket(store, t.id, 41, { now: T0 });
    assert.equal(store.getTicket(t.id).rating_score, 5);
    assert.throws(() => portal.rateTicket(store, acme, t.id, 2), /already been rated/);
  });
  ```
  Run `node --test test/rating.test.js`.
  Evidence: every test fails with "portal.rateTicket is not a function" or a missing field, none passes by accident.
- [ ] 2. `src/tickets.js`: in `createTicket` after `closed_at: null,` add `rating_score: null,` and `rated_at: null,`. Add
  ```js
  const MIN_SCORE = 1;
  const MAX_SCORE = 5;

  // The customer's verdict on a resolved ticket. One rating per ticket, ever. Callers check the organisation first.
  function rateTicket(store, id, score, { now = new Date() } = {}) {
    if (!Number.isInteger(score) || score < MIN_SCORE || score > MAX_SCORE) throw new Error('a rating is a whole number from 1 to 5');
    const t = mustGet(store, id);
    if (t.status !== STATUS.RESOLVED) throw new Error(`cannot rate a ${t.status} ticket`);
    const rated = store.rateTicket(id, { score, at: now.toISOString() });
    if (!rated) throw new Error('this ticket has already been rated');
    return rated;
  }
  ```
  and add `rateTicket` to `module.exports`.
- [ ] 3. `src/store.js`: after `updateTicket` add
  ```js
    // Writes the rating only if there is none yet; null when the ticket was already rated. Postgres:
    // UPDATE tickets SET rating_score = $2, rated_at = $3 WHERE id = $1 AND rating_score IS NULL RETURNING *.
    rateTicket(id, { score, at }) {
      const t = tickets.get(id);
      if (!t) throw new Error(`no ticket ${id}`);
      if (t.rating_score != null) return null;
      Object.assign(t, { rating_score: score, rated_at: at });
      return { ...t };
    },
  ```
- [ ] 4. `src/portal.js`: change line 4 to `const { STATUS, createTicket, rateTicket: rate } = require('./tickets');`, and before `module.exports` add
  ```js
  // A customer rates a resolved ticket of their organisation. Another organisation's ticket looks like a missing one.
  function rateTicket(store, customer, id, score, { now = new Date() } = {}) {
    const t = store.getTicket(id);
    if (!t || t.org_id !== customer.orgId) return null;
    rate(store, id, score, { now });
    return getMyTicket(store, customer, id);
  }
  ```
  Add `rateTicket` to the exports.
- [ ] 5. Run `node --test`. Evidence: all green, including the six new tests.
- [ ] 6. Negative control for isolation: delete `|| t.org_id !== customer.orgId` in `portal.rateTicket`, run
  `node --test test/rating.test.js`; the other-organisation test must fail. Revert and show green.
- [ ] 7. Append a "Rating" section to `handover.md`: `ALTER TABLE tickets ADD COLUMN rating_score smallint CHECK (rating_score BETWEEN 1 AND 5), ADD COLUMN rated_at timestamptz;`
  and that the export file gains `rating_score` and `rated_at` (D4).
- [ ] 8. Commit: `feat: customers rate a resolved ticket once`.

## Exit criteria

New tests green, isolation negative control shown failing, full suite green.

## Risks

- The error text for "open" reads "a open ticket", same as the existing reopen message; left as is for consistency.
- Rating fields in `exports/tickets.json` are new to finance; additive, flagged in D4.

